import assert from 'node:assert/strict';
import fs from 'node:fs';
import { pathToFileURL } from 'node:url';

// Synthetic HTML is generated by test-otp-email-layout.ts. No provider calls.
const { chromium } = await import(process.env.PLAYWRIGHT_MODULE
  ? pathToFileURL(process.env.PLAYWRIGHT_MODULE).href : 'playwright');
const browser = await chromium.launch({ channel: 'chrome', headless: true });
try {
  const page = await browser.newPage();
  await page.route('**/*', route => new URL(route.request().url()).pathname === '/branding/veli-randevu-logo.png'
    ? route.fulfill({contentType:'image/png',body:fs.readFileSync('public/branding/veli-randevu-logo.png')}) : route.abort());
  for (const mail of JSON.parse(fs.readFileSync('.cache/roster-review/otp-emails.json','utf8'))) {
  for (const width of [375, 390, 430, 768, 1024, 1440]) {
    await page.setViewportSize({ width, height: 844 });
    await page.setContent(mail.html);
    const selected = await page.locator('[data-email-otp]').evaluate(el => { const selection=window.getSelection();const range=document.createRange();range.selectNodeContents(el);selection.removeAllRanges();selection.addRange(range);return selection.toString(); });
    assert.equal(selected,'123456','OTP is selectable as six contiguous digits');
    const code = await page.getByText('123456', { exact: true }).boundingBox();
    const greeting = await page.locator('p').filter({ hasText: /^Merhaba/ }).boundingBox();
    assert(code && greeting && code.y < greeting.y);
    assert(code.y + code.height < 450, 'code must be above the initial mobile fold');
    assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth));
    await page.evaluate(()=>window.getSelection()?.removeAllRanges());
    if (width === 390) await page.screenshot({ path: '.cache/roster-review/otp-email-mobile.png' });
  }
  }
  console.log('All OTP email responsive HTML PASS: code visible above greeting/fold, no horizontal overflow at 375–1440px. Chromium only; Gmail/Apple Mail/Outlook manual checks required.');
} finally {
  await browser.close();
}
